8	/**
9	 Parses and sanitizes the inline CSS of an element's {@code style} attribute, one declaration at a time. The parser is
10	 a small hand scanner rather than a full CSS parser: declarations are split on semicolons while tracking the actual
11	 nesting of strings, parentheses, block comments, and CSS backslash escapes, so that punctuation inside strings
12	 ({@code font-family: 'Calibri;'}) or functions ({@code background: url(/img;a.png)}) cannot break out of its
13	 declaration.
14	
15	 <p>Declarations with no recognizable property, an unclosed function or string (recovered only at a newline, per the
16	 CSS bad-string rule), unbalanced parentheses, or a forbidden or unverifiable external reference are dropped
17	 individually; surrounding safe declarations, other attributes, and the element's text are untouched. An unclosed
18	 comment is itself an unbounded fragment and is dropped, but scanning recovers at the next semicolon so that later
19	 declarations are still parsed independently. Comment text is emitted verbatim, so every comment — including one in a
20	 leading, name-to-colon, or function-name separator position — is scanned for a concealed reference; a rejected URL
21	 can never survive inside a comment.
22	 Each surviving declaration is scanned for references ({@code url(...)}, the legacy {@code expression(...)}
23	 function, and an {@code @import} at-rule) and every reference found is normalized through CSS unescaping and checked
24	 against the safelist's URL rules. Repeated separators and other degenerate input never throw and never cause
25	 following declarations to be joined into a rejected value.</p>
26	
27	 <p>The cleaner is stateless and thread-safe; all per-value state lives on the local parse stack.</p>
28	 */
29	final class StyleCleaner {
30	    private final Safelist safelist;
31	    private final String tagName;
32	    private final Element el;
33	
34	    private StyleCleaner(Safelist safelist, String tagName, Element el) {
35	        this.safelist = safelist;
36	        this.tagName = tagName;
37	        this.el = el;
38	    }
39	
40	    /**
41	     Cleans an inline {@code style} attribute value declaration by declaration, preserving the order and original
42	     text of every declaration that survives.
43	     @return the cleaned value, or {@code null} when no declaration survives (in which case the attribute is removed)
44	     */
45	    static String clean(Safelist safelist, String tagName, Element el, String value) {
46	        return new StyleCleaner(safelist, tagName, el).clean(value);
47	    }
48	
49	    private String clean(String value) {
50	        StringBuilder out = StringUtil.borrowBuilder();
51	        int length = value.length();
52	        int[] match = parenMatches(value); // index of each parenthesis's mate, or -1 when unmatched
53	        int[] opens = new int[length]; // positions of the currently open parentheses
54	        int segStart = 0;
55	        int parenDepth = 0;
56	        boolean segmentBad = false; // this segment already contains a malformed construct
57	        int i = 0;
58	        while (i < length) {
59	            char c = value.charAt(i);
60	            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
61	                i += 2;
62	                continue;
63	            }
64	            if (c == '"' || c == '\'') {
65	                int[] quote = scanQuoted(value, i + 1, c);
66	                if (quote[1] == 1) {
67	                    i = quote[0] + 1;
68	                } else {
69	                    segmentBad = true; // a bad-string token makes only this declaration malformed
70	                    i = quote[1] == 2 ? quote[0] + 1 : quote[0]; // recover at the newline, or at the next ';'
71	                }
72	                continue;
73	            }
74	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
75	                int close = value.indexOf("*/", i + 2);
76	                if (close < 0) {
77	                    // an unterminated comment cannot be bounded and so invalidates only its own fragment: recover at
78	                    // the next ';' so that following declarations stay independently parseable. When no ';' remains,
79	                    // the text before the comment is still validated on its own merits.
80	                    int semi = value.indexOf(';', i + 2);
81	                    if (semi < 0) {
82	                        appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
83	                        segStart = length;
84	                        break;
85	                    }
86	                    segmentBad = true;
87	                    i = semi; // the ';' branch ends the malformed fragment and resets for the next declaration
88	                    continue;
89	                }
90	                i = close + 2;
91	                continue;
92	            }
93	            if (c == '(') {
94	                opens[parenDepth++] = i;
95	            } else if (c == ')') {
96	                if (parenDepth > 0) parenDepth--;
97	                else segmentBad = true; // a stray ')' makes this declaration malformed
98	            } else if (c == ';') {
99	                if (parenDepth > 0 && match[opens[parenDepth - 1]] >= 0) {
100	                    // the ';' is content of a function that closes later (e.g. an unquoted data: URL); keep scanning
101	                    i++;
102	                    continue;
103	                }
104	                // otherwise end here; a function that never closes only invalidates this declaration
105	                appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
106	                segStart = i + 1;
107	                segmentBad = false;
108	                parenDepth = 0;
109	            }
110	            i++;
111	        }
112	        if (segStart < length) appendSafeDeclaration(value, segStart, length, segmentBad || parenDepth != 0, out);
113	
114	        if (out.length() == 0) {
115	            StringUtil.releaseBuilderVoid(out);
116	            return null;
117	        }
118	        return StringUtil.releaseBuilder(out);
119	    }
120	
121	    /**
122	     Computes the matching parenthesis of every balanced {@code (} and {@code )} in the value, applying the same
123	     * lexical rules (escapes, quoted strings with bad-string recovery, and comments) as the declaration walk. An
124	     * unmatched parenthesis maps to {@code -1}; a single linear pass keeps style cleaning O(n) even when a value
125	     * contains many semicolons nested in functions.
126	     */
127	    private int[] parenMatches(String value) {
128	        int length = value.length();
129	        int[] match = new int[length];
130	        Arrays.fill(match, -1);
131	        int[] stack = new int[length];
132	        int depth = 0;
133	        int i = 0;
134	        while (i < length) {
135	            char c = value.charAt(i);
136	            if (c == '\\') { i += 2; continue; }
137	            if (c == '"' || c == '\'') {
138	                int[] quote = scanQuoted(value, i + 1, c);
139	                i = quote[1] == 0 ? quote[0] : quote[0] + 1; // at the recovered ';', or past the quote/newline
140	                continue;
141	            }
142	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
143	                int close = value.indexOf("*/", i + 2);
144	                if (close < 0) {
145	                    // mirror the declaration walk: an unterminated comment invalidates only its own fragment, and
146	                    // scanning recovers at the next ';'. Any parentheses opened in that dropped fragment are
147	                    // abandoned there, so the nesting depth resets with it.
148	                    int semi = value.indexOf(';', i + 2);
149	                    if (semi < 0) break;
150	                    depth = 0;
151	                    i = semi;
152	                    continue;
153	                }
154	                i = close + 2;
155	                continue;
156	            }
157	            if (c == '(') {
158	                stack[depth++] = i;
159	            } else if (c == ')') {
160	                if (depth > 0) {
161	                    int open = stack[--depth];
162	                    match[open] = i;
163	                    match[i] = open;
164	                }
165	            }
166	            i++;
167	        }
168	        return match;
169	    }
170	
171	    /**
172	     * <ul>
173	     *   <li>state {@code 1}: the closing quote was found at {@code end};</li>
174	     *   <li>state {@code 2}: the string was recovered at the newline at {@code end} (the CSS bad-string rule; later
175	     *       declarations stay independently parseable);</li>
176	     *   <li>state {@code 0}: neither quote nor newline remains; {@code end} is the index of the first semicolon at
177	     *       or after the opening quote (the malformed declaration is cut there), or the value length when none.</li>
178	     * </ul>
179	     */
180	    private int[] scanQuoted(String value, int from, char quote) {
181	        int length = value.length();
182	        int firstSemi = -1;
183	        for (int i = from; i < length; i++) {
184	            char c = value.charAt(i);
185	            if (c == '\\') { i++; continue; }
186	            if (c == quote) return new int[] {i, 1};
187	            if (c == '\n' || c == '\r') return new int[] {i, 2}; // bad-string recovery at a CSS newline
188	            if (c == ';' && firstSemi < 0) firstSemi = i;
189	        }
190	        return new int[] {firstSemi >= 0 ? firstSemi : length, 0};
191	    }
192	
193	    /**
194	     Validates the declaration at {@code [start, end)} and, when safe, appends its verbatim text to {@code out}.
195	     @param structurallyBad the containing walk already found a malformed construct (a bad-string token)
196	     */
197	    private void appendSafeDeclaration(String value, int start, int end, boolean structurallyBad, StringBuilder out) {
198	        if (structurallyBad) return;
199	        int p = skipSpaceAndComments(value, start, end);
200	        if (p < 0) return; // an unterminated or unsafe leading comment rejects only this declaration
201	        int q = end;
202	        while (q > p && isCssSpace(value.charAt(q - 1))) q--;
203	        if (p == q) return; // whitespace-only fragment, e.g. from a duplicated ';'
204	        int nameStart = p;
205	
206	        // an at-rule in a declaration position: only @import is meaningful inline, and its reference must pass
207	        if (value.charAt(p) == '@') {
208	            if (isSafeImportDeclaration(value, p, q)) append(out, value, start, q);
209	            return;
210	        }
211	        // property: a plain CSS identifier (including a vendor prefix such as -webkit-*) or a custom property
212	        // (--name). Escapes, comments, and quotes are not accepted in a declaration name.
213	        boolean custom = false;
214	        if (value.charAt(p) == '-') {
215	            if (p + 1 < end && value.charAt(p + 1) == '-') {
216	                p += 2;
217	                custom = true;
218	                if (p >= q || !isIdentChar(value.charAt(p))) return; // "--" alone is not a property name
219	                while (p < q && isIdentChar(value.charAt(p))) p++;
220	            } else {
221	                if (p + 1 >= q || !isIdentStart(value.charAt(p + 1))) return; // a bare '-' is not a property name
222	                p++; // let the ordinary identifier run consume the vendor-prefixed remainder
223	            }
224	        }
225	        if (!custom) {
226	            if (p >= q || !isIdentStart(value.charAt(p))) return; // no property name
227	            do { p++; } while (p < q && isIdentChar(value.charAt(p)));
228	        }
229	        int afterName = skipSpaceAndComments(value, p, q); // whitespace/comments may sit between the name and the ':'
230	        if (afterName < 0) return; // an unterminated or unsafe comment in the gap rejects only this declaration
231	        if (afterName >= q || value.charAt(afterName) != ':') return; // no ':' (empty fragment, junk, duplicate ';')
232	        p = afterName + 1; // step past ':'
233	
234	        if (isDangerousProperty(value, nameStart)) return; // known script-entry properties, regardless of value
235	        // a custom property (--name) holds arbitrary free text: its value is scanned as one string, so a colon that is
236	        // not part of a reference (e.g. "--x: https://example.com" or a time such as "12:00"), a stray quote, or an
237	        // at-keyword other than @import is preserved verbatim; only its references decide its fate
238	        boolean safe = custom
239	            ? freeTextIsSafe(value.substring(p, q))
240	            : referencesAreSafe(value, p, q);
241	        if (safe) append(out, value, start, q);
242	    }
243	
244	    /** Appends a surviving declaration, separated from any earlier ones by a single semicolon. */
245	    private void append(StringBuilder out, String value, int from, int to) {
246	        if (out.length() > 0) out.append(';');
247	        out.append(value, from, to);
248	    }
249	
250	    /**
251	     Validates an entire {@code @import} declaration: its leading reference (a quoted URL or a {@code url(...)}) must
252	     * pass the URL rules, and any trailing layer/media/supports conditions must themselves contain no unsafe
253	     * reference.
254	     */
255	    private boolean isSafeImportDeclaration(String value, int at, int end) {
256	        int i = at + 1;
257	        if (!matchesName(value, i, end, "import")) return false;
258	        i += 6;
259	        while (i < end && isCssSpace(value.charAt(i))) i++;
260	        if (i == end) return false;
261	        int afterRef;
262	        char c = value.charAt(i);
263	        if (c == '"' || c == '\'') {
264	            int[] quote = scanQuoted(value, i + 1, c);
265	            if (quote[1] != 1) return false;
266	            if (!safelist.isSafeStyleUrl(tagName, el, unescape(value.substring(i + 1, quote[0])))) return false;
267	            afterRef = quote[0] + 1;
268	        } else if (matchesName(value, i, end, "url")) {
269	            int k = skipSeparators(value, i + 3, end);
270	            if (k < 0 || k >= end || value.charAt(k) != '(') return false;
271	            int argEnd = matchingParen(value, k + 1, end);
272	            if (argEnd < 0 || !isSafeUrlArgument(value, k + 1, argEnd)) return false;
273	            afterRef = argEnd + 1;
274	        } else {
275	            return false;
276	        }
277	        return referencesAreSafe(value, afterRef, end);
278	    }
279	
280	    /**
281	     Advances past CSS whitespace and complete block comments, scanning every skipped comment body for a concealed
282	     reference: the comment text is emitted verbatim, so a rejected URL in a leading comment, a name-to-colon gap, or
283	     a function-name separator must not escape the URL rules. Returns {@code -1} when a comment is unterminated or
284	     carries an unsafe reference.
285	     */
286	    private int skipSpaceAndComments(String value, int i, int end) {
287	        while (i < end) {
288	            char c = value.charAt(i);
289	            if (isCssSpace(c)) { i++; continue; }
290	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
291	                int close = value.indexOf("*/", i + 2);
292	                if (close < 0 || close >= end) return -1;
293	                if (!freeTextIsSafe(value.substring(i + 2, close))) return -1;
294	                i = close + 2;
295	                continue;
296	            }
297	            break;
298	        }
299	        return i;
300	    }
301	
302	    /** Whitespace and comments may separate a function name from its opening parenthesis ({@code url /**\/ ( ... )}). */
303	    private int skipSeparators(String value, int i, int end) {
304	        return skipSpaceAndComments(value, i, end);
305	    }
306	
307	    /**
308	     Tests whether the gap {@code [nameEnd, sepEnd)} just skipped is made up solely of block comments with no
309	     * whitespace and glues the preceding name to another identifier run that is itself followed (optionally via
310	     * separators) by {@code (}. A comment wedged between two identifier runs ({@code ur/**\/l( ... )} or
311	     * {@code expr/**\/ession( ... )}) does not join them under a strict CSS tokenizer, but a lenient engine could
312	     * read the glued run as a single function token; such a declaration is rejected rather than risk a split
313	     * {@code url} or {@code expression} escaping recognition. Two bare runs without a following call
314	     * ({@code a/**\/b}) stay untouched.
315	     */
316	    private boolean commentGluesNameToIdent(String value, int nameEnd, int sepEnd, int end) {
317	        if (sepEnd >= end || !isIdentChar(value.charAt(sepEnd))) return false;
318	        int i = nameEnd;
319	        boolean sawComment = false;
320	        while (i < sepEnd) {
321	            char c = value.charAt(i);
322	            if (isCssSpace(c)) return false; // real whitespace keeps the two runs distinct tokens
323	            if (c == '/' && i + 1 < sepEnd && value.charAt(i + 1) == '*') {
324	                int close = value.indexOf("*/", i + 2);
325	                if (close < 0 || close > sepEnd) return false;
326	                sawComment = true;
327	                i = close + 2;
328	                continue;
329	            }
330	            return false;
331	        }
332	        if (!sawComment) return false;
333	        int k = sepEnd;
334	        while (k < end && isIdentChar(value.charAt(k))) k++; // the run the comment glued onto
335	        k = skipSeparators(value, k, end);
336	        return k >= 0 && k < end && value.charAt(k) == '(';
337	    }
338	
339	    /**
340	     Denies the legacy script-entry properties that load executable or behavior-bound content even through an
341	     * otherwise allowed-looking {@code url(...)}: {@code -moz-binding} (XBL) and IE's {@code behavior}. The name is
342	     * the plain identifier run starting at {@code nameStart}; a comment appended to the name cannot change the
343	     * comparison.
344	     */
345	    private boolean isDangerousProperty(String value, int nameStart) {
346	        int p = nameStart;
347	        while (p < value.length() && isIdentChar(value.charAt(p))) p++;
348	        String name = value.substring(nameStart, p);
349	        return name.equalsIgnoreCase("-moz-binding") || name.equalsIgnoreCase("behavior");
350	    }
351	
352	    /**
353	     Walks a declaration value in a single lexical pass: strings, comments, escapes, and balanced functions are
354	     recognized exactly as in declaration splitting. Block comments are skipped entirely (their text is never parsed
355	     as CSS); string contents are still scanned for a concealed {@code url(...)}-shaped reference, because when the
356	     string is itself the argument of {@code url()} the browser unescapes it before fetching; every {@code url(...)}
357	     argument, an {@code @import} reference, and the legacy {@code expression(...)} function is normalized and checked
358	     against the safelist. Unbalanced parentheses, an unterminated string or comment, or any failed reference check
359	     rejects the declaration.
360	     */
361	    private boolean referencesAreSafe(String value, int start, int end) {
362	        int parenDepth = 0;
363	        int i = start;
364	        while (i < end) {
365	            char c = value.charAt(i);
366	            if (c == '\\') { i += 2; continue; }
367	            if (c == '"' || c == '\'') {
368	                int[] quote = scanQuoted(value, i + 1, c);
369	                if (quote[1] != 1) return false; // no bad-string recovery inside a value being checked
370	                if (!freeTextIsSafe(value.substring(i + 1, quote[0]))) return false;
371	                i = quote[0] + 1;
372	                continue;
373	            }
374	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
375	                int close = value.indexOf("*/", i + 2);
376	                if (close < 0 || close >= end) return false; // unterminated comment within the declaration
377	                // comment text is never a declaration, but a reference concealed in a comment must still pass the
378	                // same URL rules so that a rejected URL can never survive in the emitted attribute
379	                if (!freeTextIsSafe(value.substring(i + 2, close))) return false;
380	                i = close + 2;
381	                continue;
382	            }
383	            if (c == '(') { parenDepth++; i++; continue; }
384	            if (c == ')') {
385	                if (parenDepth == 0) return false; // unmatched ')'
386	                parenDepth--;
387	                i++;
388	                continue;
389	            }
390	            if (c == '@') return false; // no at-rule (e.g. a buried @import) is valid inside a declaration value
391	            if (isIdentStart(c) || c == '-') {
392	                int[] name = readName(value, i, end);
393	                int nameEnd = name[0];
394	                String fnName = name[1] == 1 ? unescape(value.substring(i, nameEnd)) : value.substring(i, nameEnd);
395	                int j = skipSeparators(value, nameEnd, end);
396	                if (j < 0) return false; // an unterminated or unsafe comment after the name rejects the declaration
397	                if (commentGluesNameToIdent(value, nameEnd, j, end)) return false; // e.g. ur/**/l(...)
398	                if (j < end && value.charAt(j) == '(') {
399	                    int argEnd = matchingParen(value, j + 1, end);
400	                    if (argEnd < 0) return false;
401	                    // a function name whose escapes decode to punctuation (e.g. "l\;expression") is not a real CSS
402	                    // function token; reject rather than risk it being read as two tokens by a quirky engine
403	                    if (!isPlainName(fnName)) return false;
404	                    if (fnName.equalsIgnoreCase("expression")) return false; // legacy JScript entry point
405	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(value, j + 1, argEnd)) return false;
406	                    i = j; // resume at '(' so a nested url()/expression() inside the arguments is also checked
407	                    continue;
408	                }
409	                i = nameEnd;
410	                continue;
411	            }
412	            i++;
413	        }
414	        return parenDepth == 0;
415	    }
416	
417	    /** Tests that a function name is a plain identifier, with no escape that decoded to punctuation or whitespace. */
418	    private static boolean isPlainName(String name) {
419	        int length = name.length();
420	        if (length == 0) return false;
421	        for (int k = 0; k < length; k++) {
422	            char c = name.charAt(k);
423	            boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
424	                || (c >= '0' && c <= '9') || c == '-' || c == '_';
425	            if (!ok) return false;
426	        }
427	        return true;
428	    }
429	
430	    /**
431	     Reads a CSS name token (identifier characters, plus backslash escapes) from {@code from}. Returns
432	     {@code [end, escaped]}: {@code end} is the index after the token, and {@code escaped} is 1 when it contained a
433	     backslash. A leading run of dashes is consumed so that e.g. {@code -moz-binding} reads as one token.
434	     */
435	    private int[] readName(String value, int from, int end) {
436	        int i = from;
437	        int escaped = 0;
438	        while (i < end) {
439	            char c = value.charAt(i);
440	            if (c == '\\') {
441	                if (i + 1 >= end) break;
442	                escaped = 1;
443	                i += 2;
444	                continue;
445	            }
446	            if (isIdentChar(c)) { i++; continue; }
447	            break;
448	        }
449	        return new int[] {i, escaped};
450	    }
451	
452	    /**
453	     Applies the same URL rules to text that is not itself parsed as declarations — the body of a quoted string, a
454	     * block comment, or the value of a custom property. Such text cannot introduce a declaration, but a rejected
455	     * reference must not survive in the emitted style, so every {@code url(...)}-shaped reference and every
456	     * {@code @import} reference is extracted (CSS-escapes normalized) and checked; the legacy
457	     * {@code expression(...)} function is always rejected.
458	     */
459	    private boolean freeTextIsSafe(String text) {
460	        int end = text.length();
461	        int i = 0;
462	        while (i < end) {
463	            char c = text.charAt(i);
464	            if (c == '\\') { i += 2; continue; }
465	            if (c == '@' && matchesName(text, i + 1, end, "import")) {
466	                if (!freeTextImportIsSafe(text, i + 7, end)) return false;
467	                i += 7;
468	                continue;
469	            }
470	            if (isIdentStart(c) || c == '-') {
471	                int[] name = readName(text, i, end);
472	                int j = skipSeparators(text, name[0], end);
473	                if (j < 0) return false;
474	                if (commentGluesNameToIdent(text, name[0], j, end)) return false; // e.g. ur/**/l(...)
475	                if (j < end && text.charAt(j) == '(') {
476	                    String fnName = name[1] == 1 ? unescape(text.substring(i, name[0])) : text.substring(i, name[0]);
477	                    int argEnd = matchingParen(text, j + 1, end);
478	                    if (argEnd < 0) return false;
479	                    if (!isPlainName(fnName)) return false;
480	                    if (fnName.equalsIgnoreCase("expression")) return false;
481	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(text, j + 1, argEnd)) return false;
482	                    i = j; // resume at '(' so a nested url()/expression() in the arguments is also checked
483	                    continue;
484	                }
485	                i = name[0];
486	                continue;
487	            }
488	            i++;
489	        }
490	        return true;
491	    }
492	
493	    /** Checks the quoted-string or {@code url(...)} reference of an {@code @import} found in free text. */
494	    private boolean freeTextImportIsSafe(String text, int from, int end) {
495	        int i = from;
496	        while (i < end && isCssSpace(text.charAt(i))) i++;
497	        if (i >= end) return true; // a dangling "@import" with no reference is inert junk
498	        char c = text.charAt(i);
499	        if (c == '"' || c == '\'') {
500	            int[] quote = scanQuoted(text, i + 1, c);
501	            if (quote[1] != 1) return false;
502	            return safelist.isSafeStyleUrl(tagName, el, unescape(text.substring(i + 1, quote[0])));
503	        }
504	        if (matchesName(text, i, end, "url")) {
505	            int k = skipSeparators(text, i + 3, end);
506	            if (k < 0 || k >= end || text.charAt(k) != '(') return false;
507	            int argEnd = matchingParen(text, k + 1, end);
508	            return argEnd >= 0 && isSafeUrlArgument(text, k + 1, argEnd);
509	        }
510	        return false;
511	    }
512	
513	    /** Extracts and validates the single URL argument of a {@code url(...)} function. */
514	    private boolean isSafeUrlArgument(String value, int from, int end) {
515	        int i = from;
516	        while (i < end && isCssSpace(value.charAt(i))) i++;
517	        int j = end;
518	        while (j > i && isCssSpace(value.charAt(j - 1))) j--;
519	        if (i == j) return false; // url() with no reference
520	
521	        char first = value.charAt(i);
522	        String raw;
523	        if (first == '"' || first == '\'') {
524	            int[] quote = scanQuoted(value, i + 1, first);
525	            if (quote[1] != 1 || quote[0] + 1 != j) return false; // unterminated or trailing junk inside the quotes
526	            raw = value.substring(i + 1, quote[0]);
527	            for (int k = 0; k < raw.length(); k++) { // the closing quote may not appear inside, escaped or not
528	                char c = raw.charAt(k);
529	                if (c == '\\') { k++; continue; }
530	                if (c == first) return false;
531	            }
532	        } else {
533	            // an unquoted URL token is a single run: bare whitespace or quotes are syntax errors, not part of the URL
534	            for (int k = i; k < j; k++) {
535	                char c = value.charAt(k);
536	                if (c == '\\') { k++; continue; }
537	                if (c == '"' || c == '\'' || isCssSpace(c)) return false;
538	            }
539	            raw = value.substring(i, j);
540	        }
541	        return safelist.isSafeStyleUrl(tagName, el, unescape(raw));
542	    }
543	
544	    /** Returns the index of the ')' matching the '(' whose argument starts at {@code from}, or {@code -1}. */
545	    private int matchingParen(String value, int from, int end) {
546	        int depth = 1;
547	        int i = from;
548	        while (i < end) {
549	            char c = value.charAt(i);
550	            if (c == '\\') { i += 2; continue; }
551	            if (c == '"' || c == '\'') {
552	                int[] quote = scanQuoted(value, i + 1, c);
553	                if (quote[1] != 1) return -1;
554	                i = quote[0] + 1;
555	                continue;
556	            }
557	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
558	                int close = value.indexOf("*/", i + 2);
559	                if (close < 0 || close >= end) return -1; // an unterminated comment leaves the function unclosed
560	                i = close + 2;
561	                continue;
562	            }
563	            if (c == '(') depth++;
564	            else if (c == ')') { depth--; if (depth == 0) return i; }
565	            i++;
566	        }
567	        return -1;
568	    }
569	
570	    private boolean matchesName(String value, int from, int end, String name) {
571	        int len = name.length();
572	        if (from + len > end) return false;
573	        for (int k = 0; k < len; k++) {
574	            char a = value.charAt(from + k);
575	            char b = name.charAt(k);
576	            if (a != b && a != Character.toUpperCase(b)) return false;
577	        }
578	        return true;
579	    }
580	
581	    /**
582	     Decodes CSS backslash escapes in a URL token, mirroring how a browser reads the reference: a {@code \}{@code hEX}
583	     run (up to six hex digits, optionally followed by one whitespace delimiter) becomes its code point, and any other
584	     backslash-prefixed character collapses to that character. An obfuscated scheme such as {@code java\73cript:} or
585	     {@code \6a avascript:} therefore cannot hide from the protocol check. A NUL code point is dropped, matching the
586	     CSS requirement to replace it.
587	     */
588	    static String unescape(String value) {
589	        if (value.indexOf('\\') == -1) return value;
590	        int length = value.length();
591	        StringBuilder sb = null;
592	        int i = 0;
593	        while (i < length) {
594	            char c = value.charAt(i);
595	            if (c == '\\' && i + 1 < length) {
596	                if (sb == null) {
597	                    sb = new StringBuilder(length);
598	                    sb.append(value, 0, i);
599	                }
600	                int h = i + 1;
601	                int hexEnd = h;
602	                while (hexEnd < length && hexEnd - h < 6 && isHex(value.charAt(hexEnd))) hexEnd++;
603	                if (hexEnd > h) {
604	                    int code = Integer.parseInt(value.substring(h, hexEnd), 16);
605	                    if (hexEnd < length && isCssSpace(value.charAt(hexEnd))) hexEnd++;
606	                    // per the CSS spec, NUL, surrogates, and values above the Unicode range become U+FFFD
607	                    if (code == 0 || code > Character.MAX_CODE_POINT
608	                        || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
609	                        code = 0xFFFD;
610	                    sb.appendCodePoint(code);
611	                    i = hexEnd;
612	                } else {
613	                    sb.append(value.charAt(i + 1));
614	                    i += 2;
615	                }
616	                continue;
617	            }
618	            if (sb != null) sb.append(c);
619	            i++;
620	        }
621	        return sb != null ? sb.toString() : value;
622	    }
623	
624	    private static boolean isCssSpace(char c) {
625	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
626	    }
627	
628	    private static boolean isHex(char c) {
629	        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
630	    }
631	
632	    private static boolean isIdentStart(char c) {
633	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_';
634	    }
635	
636	    private static boolean isIdentChar(char c) {
637	        return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-';
638	    }
639	}
