package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class Probe {
    static final String Base = "https://example.com/a/b";

    static String clean(String style) {
        Safelist sl = Safelist.relaxed().addAttributes(":all", "style");
        Document dirty = Jsoup.parseBodyFragment("<div style=\"" + style + "\">x</div>", Base);
        return new Cleaner(sl).clean(dirty).body().html();
    }

    public static void main(String[] args) {
        // marker: dangerous content survives if output contains "javascript" / "expression" / "vbscript"
        String[] attacks = {
            // leading hex escape in function name
            "background:\\75rl(javascript:alert(1));color:red",
            "background:\\75 rl(javascript:alert(1));color:red",
            "background:color:red",
            "background:\\65xpression(alert(1));color:red",
            "background:\\65 xpression(alert(1));color:red",
            "background:\\55RL(javascript:alert(1));color:red",
            "background:\\55 RL(JAVASCRIPT:alert(1));color:red",
            // mid-name hex escape with whitespace delimiter
            "background:u\\72 l(javascript:alert(1));color:red",
            "background:exp\\72 ession(alert(1));color:red",
            "background:expre\\73 sion(alert(1));color:red",
            // nested inside another function
            "width:calc(\\75rl(javascript:alert(1)));color:red",
            "width:calc(\\75 rl(javascript:alert(1)));color:red",
            "width:calc(1+u\\72 l(javascript:alert(1)));color:red",
            // inside a quoted string
            "font-family:'\\75rl(javascript:alert(1))';color:red",
            "font-family:\"\\65xpression(alert(1))\";color:red",
            // custom property
            "--x:\\75rl(javascript:alert(1));color:red",
            "--x:exp\\72 ession(alert(1));color:red",
            // inside a comment
            "color:red;x:y /* \\75rl(javascript:alert(1)) */",
            "color:red;x:y /* exp\\72 ession(alert(1)) */",
            // via HTML entity encoding of the backslash
            "background:&#92;75rl(javascript:alert(1));color:red",
            "background:&#92;65xpression(alert(1));color:red",
            // multi-layer nesting / strings
            "width:calc(var(\\75 rl(javascript:1)));color:red",
            "content:'a(\\75rl(javascript:1))';color:red",
            // tab/newline as hex delimiter
            "background:\\75\trl(javascript:alert(1));color:red",
            "background:u\\72\tl(javascript:alert(1));color:red",
            // expression double-escape variants
            "background:\\65\\78\\70\\72\\65\\73\\73\\69\\6f\\6e(alert(1));color:red",
            // @import escaped
            "@import \\75rl(javascript:alert(1));color:red",
            // colon hex encoded after scheme unescape
            "background:url(javascript\\3aalert(1));color:red",
            "background:url(java\\73 cript:alert(1));color:red",
            // url name split with escape + no delim then letters
            "background:\\75 rl(//evil.com/x);color:red",
        };
        for (String a : attacks) {
            String out;
            try {
                out = clean(a);
            } catch (Exception e) {
                out = "THREW " + e;
            }
            boolean survives = out.contains("javascript") || out.contains("expression")
                || out.contains("vbscript") || out.contains("alert(1)") || out.contains("//evil");
            System.out.println((survives ? "SURVIVES " : "blocked  ") + " | " + out.replace("\n", "\\n"));
            System.out.println("           in: " + a.replace("\n", "\\n").replace("\t", "\\t"));
        }
    }
}

