package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class Probe2 {
    static final String Base = "https://example.com/a/b";

    static String clean(String style, String base) {
        Safelist sl = Safelist.relaxed().addAttributes(":all", "style");
        Document dirty = Jsoup.parseBodyFragment("<div style=\"" + style + "\">x</div>", base);
        return new Cleaner(sl).clean(dirty).body().html();
    }

    static void expectKeep(String label, String style) {
        String out = clean(style, Base);
        boolean ok = out.contains(style.substring(0, Math.min(20, style.length()))) ;
        System.out.println((out.contains("color:red") && !out.contains("javascript") ? "KEEP-OK " : "FAIL    ") + label + " -> " + out);
    }

    public static void main(String[] args) {
        // escaped SAFE url must be kept, identical conclusion to literal
        String[] safe = {
            "background:\\75rl(https://example.com/x.png);color:red",
            "background:\\75 rl(https://example.com/x.png);color:red",
            "background:\\55RL(HTTPS://example.com/x.png);color:red",
            "background:u\\72 l(https://example.com/x.png);color:red",
            "background:\\75 rl(//cdn.example.com/x.png);color:red", // protocol-relative inherits https
            "background:\\75 rl(img/x.png);color:red",               // relative resolved against base
            "width:calc(\\75rl(https://example.com/x.png) + 1px);color:red",
            "--x:\\75rl(https://example.com/x.png);color:red",
            "color:red;x:y /* \\75rl(https://example.com/x.png) */",
            "@import \\75rl(https://example.com/x.css);color:red",
        };
        for (String s : safe) {
            String out = clean(s, Base);
            boolean kept = out.contains("color:red");
            System.out.println((kept ? "KEEP-OK " : "DROPPED! ") + s + "  =>  " + out);
        }

        System.out.println("--- no base, escaped relative url must be rejected ---");
        String rel = "background:\\75 rl(img/x.png);color:red";
        System.out.println(clean(rel, "") + "  (want only color:red)");

        System.out.println("--- idempotency for escaped safe decls ---");
        for (String s : new String[]{
            "background:\\75rl(https://example.com/x.png);color:red",
            "color:red;x:y /* \\75rl(https://example.com/x.png) */",
        }) {
            String once = clean(s, Base);
            String twice = clean(extractStyle(once), Base);
            System.out.println(once.equals(twice) ? "IDEM-OK  " : "IDEM-FAIL ") + once);
        }

        System.out.println("--- glued / ambiguous at-keywords ---");
        for (String s : new String[]{
            "@importurl(javascript:1);color:red",
            "@\\69mport url(javascript:1);color:red",
            "@\\69mport 'javascript:1';color:red",
            "@\\69mport \\75rl(javascript:1);color:red",
            "@impor\\74 url(javascript:1);color:red",
        }) {
            System.out.println(clean(s, Base) + "   <= " + s);
        }

        System.out.println("--- robustness: no exceptions on degenerate input ---");
        String[] weird = {
            "\\", "\\\\", "\\75", "\\75 ", "\\75  ", "x:\\", "x:\\\\", "x:\\75",
            "x:url(", "x:url( )", "x:url('", "x:url(\"", "x:calc(", "x:())",
            "x:'abc", "x:\"abc", "x:/*c", "x:;y:;z:red", "x:\\g(y)",
            "x:\\75rl( )", "x:\\75 rl(  )", "x:expression(", "x:\\65xpression(",
            "x:var(--a,)", "x:url(\\)", "x:url(\\')", "x:url(\\ )",
        };
        for (String w : weird) {
            try { System.out.println("ok  [" + w.replace("\n","\\n") + "] -> " + clean(w, Base)); }
            catch (Throwable t) { System.out.println("THREW on [" + w + "]: " + t); }
        }

        System.out.println("--- data url via escaped name still governed by data policy ---");
        Safelist dataSl = Safelist.relaxed().addAttributes(":all","style").addProtocols(":all","style","data");
        Document d = Jsoup.parseBodyFragment("<div style=\"background:\\75rl(data:image/png;base64,iVBORw0KGgo=)\">x</div>", Base);
        System.out.println("data-configured: " + new Cleaner(dataSl).clean(d).body().html());
        System.out.println("default policy: " + clean("background:\\75rl(data:image/png;base64,iVBORw0KGgo=);color:red", Base));
    }

    static String extractStyle(String html) {
        int a = html.indexOf("style=\"") + 7;
        int b = html.indexOf('"', a);
        return html.substring(a, b);
    }
}

