package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class Probe3 {
    static final String Base = "https://example.com/a/b";
    static String clean(String style) {
        Safelist sl = Safelist.relaxed().addAttributes(":all", "style");
        Document dirty = Jsoup.parseBodyFragment("<div style=\"" + style + "\">x</div>", Base);
        return new Cleaner(sl).clean(dirty).body().html();
    }
    static void t(String s) {
        String out = clean(s);
        boolean bad = out.contains("javascript") || out.contains("alert(1)") || out.contains("evil.com");
        System.out.println((bad ? "SURVIVES " : "blocked  ") + out + "   <= " + s);
    }
    public static void main(String[] args) {
        t("background:ur/**/\\6c(javascript:1);color:red");
        t("background:\\75r/**/l(javascript:1);color:red");
        t("background:\\75 r/**/l(javascript:1);color:red");
        t("background:expr/**/\\65ssion(1);color:red");
        t("background:exp\\72/**/ession(1);color:red");
        t("--x: ur/**/\\6c(javascript:1);color:red");
        t("color:red;z:y /* ur/**/\\6c(javascript:1) */");
        // glue where glued run starts with a non-escape ident still works (regression)
        t("background:ur/**/l(javascript:1);color:red");
        t("background:ur/**/l(https://example.com/x.png);color:red");
        // safe glue a/**/b preserved
        System.out.println(clean("--x: a/**/\\62;color:red"));
        // whitespace between escapes genuinely splits -> should still recognize full url name only if it decodes
        t("background:\\75 rl (javascript:1);color:red"); // url with space before paren -> still url fn
        // escaped '(' - name escapes to punctuation => reject
        t("background:url\\28javascript:1;color:red");
        // multiple escape delimiters (only ONE whitespace consumed by hex escape)
        t("background:\\75  rl(javascript:1);color:red"); // \75 + 2 spaces: 'u' then space separator then space => not url
        // backslash-backslash before rl: \\75 = escaped backslash then '75'
        t("background:\\\\75rl(javascript:1);color:red");
    }
}

